from itertools import product


def _route(data, coupon_rule, minimum_duration):
    required = data.get("required", [])
    full = (1 << len(required)) - 1
    initial_mask = sum(1 << i for i, node in enumerate(required)
                       if node == data["source"])
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start = data["start"]
    start_state = (data["source"], initial_mask, 0)
    distances = {start_state: start}
    queue = [(start, data["source"], initial_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != time:
            continue
        if (node == data["target"] and mask == full and
                (coupon_rule != "exact" or used == data["coupons"])):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < data["coupons"]:
                duration = max(minimum_duration,
                               edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            next_mask = mask
            for i, required_node in enumerate(required):
                if required_node == edge["v"]:
                    next_mask |= 1 << i
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, next_used)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, *next_state))
    return {"arrival": None}


def _build_route(coupon_rule, minimum_duration):
    return lambda data: _route(data, coupon_rule, minimum_duration)


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = (event.get("account", "default") + "|" +
                   event.get("currency", "USD"))
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        choices = []
        for name in names:
            rows = sorted(packages[name], key=lambda row: row["version"])
            choices.append([None] + rows)

        best_key = None
        best_versions = None
        for selection in product(*choices):
            installed = {name: row for name, row in zip(names, selection)
                         if row is not None}
            valid = True
            for name, bounds in roots.items():
                row = installed.get(name)
                if row is None or not bounds[0] <= row["version"] <= bounds[1]:
                    valid = False
                    break
            if not valid:
                continue
            for name, row in installed.items():
                version = row["version"]
                if version in blocked.get(name, []) or (
                        name in pins and version != pins[name]):
                    valid = False
                    break
            if not valid:
                continue

            graph = {name: [] for name in installed}
            for name, row in installed.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    target_row = installed.get(target)
                    if (target_row is None or
                            not dep["min"] <= target_row["version"] <= dep["max"]):
                        valid = False
                        break
                    graph[name].append(target)
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            pending = list(roots)
            while pending:
                name = pending.pop()
                if name in reachable:
                    continue
                row = installed.get(name)
                if row is None:
                    valid = False
                    break
                reachable.add(name)
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if not feature or feature in features:
                        pending.append(dep["name"])
            if not valid or reachable != set(installed):
                continue

            finished, active = set(), set()
            def acyclic(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not acyclic(other) for other in graph[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True
            if not all(acyclic(name) for name in graph):
                continue

            vector = tuple(installed[name]["version"] if name in installed else -1
                           for name in names)
            if best_key is None or vector < best_key:
                best_key = vector
                best_versions = {name: row["version"]
                                 for name, row in installed.items()}
        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        if mandatory & blocked or len(mandatory) > k:
            return {"error": "impossible"}

        options = [job for job in jobs if job["id"] not in blocked]
        best_value = None
        best_ids = None

        def search(index, chosen, value):
            nonlocal best_value, best_ids
            if len(chosen) == k:
                ids = tuple(sorted(job["id"] for job in chosen))
                if not mandatory.issubset(ids):
                    return
                counts = {}
                for job in chosen:
                    counts[job["group"]] = counts.get(job["group"], 0) + 1
                for group, (low, high) in quotas.items():
                    count = counts.get(group, 0)
                    if not low <= count <= high:
                        return
                if (best_value is None or value > best_value or
                        (value == best_value and ids > best_ids)):
                    best_value, best_ids = value, ids
                return
            if index == len(options) or len(chosen) + len(options) - index < k:
                return
            job = options[index]
            # Skip this job.
            search(index + 1, chosen, value)
            # Include it only if it does not overlap any selected interval.
            if all(job["end"] <= other["start"] or
                   other["end"] <= job["start"] for other in chosen):
                chosen.append(job)
                search(index + 1, chosen, value + job["value"])
                chosen.pop()

        search(0, [], 0)
        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


